package bootstrap

import "sort"

// ProviderSecretKind describes how a provider secret is represented after resolution.
type ProviderSecretKind uint8

const (
	ProviderValueSecret ProviderSecretKind = iota
	ProviderFileSecret
)

// ProviderSecretDefinition maps a secret source suffix to a provider field.
// ManagedLocation marks an internal LOCATION output generated by the resolver.
type ProviderSecretDefinition struct {
	Suffix          string
	Field           string
	Kind            ProviderSecretKind
	ManagedLocation bool
}

var providerSecretDefinitions = []ProviderSecretDefinition{
	{Suffix: "_USERNAME", Field: "username", Kind: ProviderValueSecret},
	{Suffix: "_PASSWORD", Field: "password", Kind: ProviderValueSecret},
	{Suffix: "_SSL_KEY_PASSWORD", Field: "ssl_key_password", Kind: ProviderValueSecret},
	{Suffix: "_SSL_CERT", Field: "ssl_cert_file", Kind: ProviderFileSecret},
	{Suffix: "_SSL_KEY", Field: "ssl_key_file", Kind: ProviderFileSecret},
	{Suffix: "_SSL_CA", Field: "ssl_ca_location", Kind: ProviderFileSecret, ManagedLocation: true},
}

var (
	providerSecretSuffixes     = buildProviderSecretSuffixes(true)
	providerFileSecretSuffixes = buildProviderSecretSuffixes(true, ProviderFileSecret)
	providerLocationSuffixes   = buildProviderLocationSuffixes()
)

// ProviderSecretDefinitions returns the provider secret registry.
func ProviderSecretDefinitions() []ProviderSecretDefinition {
	return append([]ProviderSecretDefinition(nil), providerSecretDefinitions...)
}

// ProviderSecretSuffixes returns normalized source and managed-output suffixes, longest first.
func ProviderSecretSuffixes() []string {
	return append([]string(nil), providerSecretSuffixes...)
}

func configuredProviderSecretSource(env Environment, base string, includeFiles bool) string {
	for _, secret := range providerSecretDefinitions {
		if secret.Kind == ProviderFileSecret && !includeFiles {
			continue
		}
		name := base + secret.Suffix
		if env[name] != "" {
			return name
		}
		fileSuffix := "FILE"
		if secret.Kind == ProviderValueSecret {
			fileSuffix = "_FILE"
		}
		if env[name+fileSuffix] != "" {
			return name + fileSuffix
		}
	}
	return ""
}

func buildProviderSecretSuffixes(includeLocations bool, kinds ...ProviderSecretKind) []string {
	suffixes := make([]string, 0, len(providerSecretDefinitions)*3)
	for _, secret := range providerSecretDefinitions {
		if len(kinds) != 0 {
			included := false
			for _, kind := range kinds {
				included = included || secret.Kind == kind
			}
			if !included {
				continue
			}
		}
		suffixes = append(suffixes, secret.Suffix)
		if secret.Kind == ProviderValueSecret {
			suffixes = append(suffixes, secret.Suffix+"_FILE")
			continue
		}
		suffixes = append(suffixes, secret.Suffix+"FILE")
		if includeLocations && secret.ManagedLocation {
			suffixes = append(suffixes, secret.Suffix+"LOCATION")
		}
	}
	sort.SliceStable(suffixes, func(i, j int) bool { return len(suffixes[i]) > len(suffixes[j]) })
	return suffixes
}

func buildProviderLocationSuffixes() []string {
	var suffixes []string
	for _, secret := range providerSecretDefinitions {
		if secret.Kind == ProviderFileSecret {
			suffixes = append(suffixes, secret.Suffix+"LOCATION")
		}
	}
	sort.SliceStable(suffixes, func(i, j int) bool { return len(suffixes[i]) > len(suffixes[j]) })
	return suffixes
}
